% SPDX-License-Identifier: EUPL-1.2
:- module(m__eu_data_protection_gdpr_special_categories_citations, [citation/2, implements/1]).
:- use_module(library(lists)).
:- use_module(library(iso_ext)).
:- use_module(library(between)).
:- use_module(library(dif)).

implements(Key) :-
    citation(Key, _).

citation(eu_reg_2016_679_art_9_1, [label - 'Regulation (EU) 2016/679 Art 9(1) (prohibition of processing of special categories of personal data)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_009.001)', verbatim - 'Processing of personal data revealing racial or ethnic origin, political opinions, religious or philosophical beliefs, or trade union membership, and the processing of genetic data, biometric data for the purpose of uniquely identifying a natural person, data concerning health or data concerning a natural person']).
citation(eu_reg_2016_679_art_9_2_a, [label - 'Regulation (EU) 2016/679 Art 9(2)(a) (explicit consent for one or more specified purposes)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_009.002_a)', verbatim - 'the data subject has given explicit consent to the processing of those personal data for one or more specified purposes, except where Union or Member State law provide that the prohibition referred to in paragraph 1 may not be lifted by the data subject']).
citation(eu_reg_2016_679_art_9_2_b, [label - 'Regulation (EU) 2016/679 Art 9(2)(b) (employment, social security and social protection law)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_009.002_b)', verbatim - 'processing is necessary for the purposes of carrying out the obligations and exercising specific rights of the controller or of the data subject in the field of employment and social security and social protection law in so far as it is authorised by Union or Member State law or a collective agreement pursuant to Member State law providing for appropriate safeguards for the fundamental rights and the interests of the data subject']).
citation(eu_reg_2016_679_art_9_2_c, [label - 'Regulation (EU) 2016/679 Art 9(2)(c) (vital interests where the data subject is incapable of giving consent)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_009.002_c)', verbatim - 'processing is necessary to protect the vital interests of the data subject or of another natural person where the data subject is physically or legally incapable of giving consent']).
citation(eu_reg_2016_679_art_9_2_d, [label - 'Regulation (EU) 2016/679 Art 9(2)(d) (not-for-profit body with a political, philosophical, religious or trade union aim)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_009.002_d)', verbatim - 'processing is carried out in the course of its legitimate activities with appropriate safeguards by a foundation, association or any other not-for-profit body with a political, philosophical, religious or trade union aim and on condition that the processing relates solely to the members or to former members of the body or to persons who have regular contact with it in connection with its purposes and that the personal data are not disclosed outside that body without the consent of the data subjects']).
citation(eu_reg_2016_679_art_9_2_e, [label - 'Regulation (EU) 2016/679 Art 9(2)(e) (personal data manifestly made public by the data subject)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_009.002_e)', verbatim - 'processing relates to personal data which are manifestly made public by the data subject']).
citation(eu_reg_2016_679_art_9_2_f, [label - 'Regulation (EU) 2016/679 Art 9(2)(f) (legal claims or courts acting in their judicial capacity)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_009.002_f)', verbatim - 'processing is necessary for the establishment, exercise or defence of legal claims or whenever courts are acting in their judicial capacity']).
citation(eu_reg_2016_679_art_9_2_g, [label - 'Regulation (EU) 2016/679 Art 9(2)(g) (substantial public interest on the basis of Union or Member State law)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_009.002_g)', verbatim - 'processing is necessary for reasons of substantial public interest, on the basis of Union or Member State law which shall be proportionate to the aim pursued, respect the essence of the right to data protection and provide for suitable and specific measures to safeguard the fundamental rights and the interests of the data subject']).
citation(eu_reg_2016_679_art_9_2_h, [label - 'Regulation (EU) 2016/679 Art 9(2)(h) (preventive or occupational medicine, health or social care)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_009.002_h)', verbatim - 'processing is necessary for the purposes of preventive or occupational medicine, for the assessment of the working capacity of the employee, medical diagnosis, the provision of health or social care or treatment or the management of health or social care systems and services on the basis of Union or Member State law or pursuant to contract with a health professional and subject to the conditions and safeguards referred to in paragraph 3']).
citation(eu_reg_2016_679_art_9_2_i, [label - 'Regulation (EU) 2016/679 Art 9(2)(i) (public interest in the area of public health)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_009.002_i)', verbatim - 'processing is necessary for reasons of public interest in the area of public health, such as protecting against serious cross-border threats to health or ensuring high standards of quality and safety of health care and of medicinal products or medical devices, on the basis of Union or Member State law which provides for suitable and specific measures to safeguard the rights and freedoms of the data subject, in particular professional secrecy']).
citation(eu_reg_2016_679_art_9_2_j, [label - 'Regulation (EU) 2016/679 Art 9(2)(j) (archiving in the public interest, scientific or historical research or statistical purposes)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_009.002_j)', verbatim - 'processing is necessary for archiving purposes in the public interest, scientific or historical research purposes or statistical purposes in accordance with Article 89(1) based on Union or Member State law which shall be proportionate to the aim pursued, respect the essence of the right to data protection and provide for suitable and specific measures to safeguard the fundamental rights and the interests of the data subject']).
citation(eu_reg_2016_679_art_9_3, [label - 'Regulation (EU) 2016/679 Art 9(3) (professional secrecy condition for point (h) processing)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_009.003)', verbatim - 'Personal data referred to in paragraph 1 may be processed for the purposes referred to in point (h) of paragraph 2 when those data are processed by or under the responsibility of a professional subject to the obligation of professional secrecy under Union or Member State law or rules established by national competent bodies or by another person also subject to an obligation of secrecy under Union or Member State law or rules established by national competent bodies']).
citation(eu_reg_2016_679_art_9_4, [label - 'Regulation (EU) 2016/679 Art 9(4) (Member State further conditions for genetic, biometric or health data)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit parag_009.004)', verbatim - 'Member States may maintain or introduce further conditions, including limitations, with regard to the processing of genetic data, biometric data or data concerning health']).
citation(eu_reg_2016_679_art_10, [label - 'Regulation (EU) 2016/679 Art 10 (processing of personal data relating to criminal convictions and offences)', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit art_010)', verbatim - 'Processing of personal data relating to criminal convictions and offences or related security measures based on Article 6(1) shall be carried out only under the control of official authority or when the processing is authorised by Union or Member State law providing for appropriate safeguards for the rights and freedoms of data subjects. Any comprehensive register of criminal convictions shall be kept only under the control of official authority']).
citation(eu_reg_2016_679_art_4_11, [label - 'Regulation (EU) 2016/679 Art 4(11) definition of consent of the data subject', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_004_11)', verbatim - 'means any freely given, specific, informed and unambiguous indication of the data subject']).
citation(eu_reg_2016_679_art_4_13, [label - 'Regulation (EU) 2016/679 Art 4(13) definition of genetic data', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_004_13)', verbatim - 'means personal data relating to the inherited or acquired genetic characteristics of a natural person which give unique information about the physiology or the health of that natural person and which result, in particular, from an analysis of a biological sample from the natural person in question']).
citation(eu_reg_2016_679_art_4_14, [label - 'Regulation (EU) 2016/679 Art 4(14) definition of biometric data', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_004_14)', verbatim - 'means personal data resulting from specific technical processing relating to the physical, physiological or behavioural characteristics of a natural person, which allow or confirm the unique identification of that natural person, such as facial images or dactyloscopic data']).
citation(eu_reg_2016_679_art_4_15, [label - 'Regulation (EU) 2016/679 Art 4(15) definition of data concerning health', ref - 'https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02016R0679-20160504 (unit point_004_15)', verbatim - 'means personal data related to the physical or mental health of a natural person, including the provision of health care services, which reveal information about his or her health status']).
